CASES = [
    ("A: 2c+1>=0", +1, F(-1, 2), F(1),  [8, -12, -2, 3]),
    ("B: 2c+1<=0", -1, F(-1),    F(-1, 2), [8, 20, -14, -11]),
]

def poly_eval(coeffs, c):
    v = F(0)
    for a in coeffs:
        v = v * c + a
    return v

# 1) Exact algebra check of the case polynomials against the rational definition.
ok_alg = True
for name, sgn, lo, hi, co in CASES:
    for k in range(-30, 31):
        c = F(k, 17)
        if 4 * (lhs_c(c, sgn) - rhs_c(c)) != poly_eval(co, c):
            ok_alg = False
print("ALGEBRA CHECK (exact, 61 rational samples per case):", "PASS" if ok_alg else "FAIL")

# 2) Sampled check of the trig-to-c identity (sampling only, not a proof).
max_err = 0.0
for i in range(-2000, 2001):
    x = i * math.pi / 500
    lhs = math.cos(x) * (math.cos(x) - math.cos(5 * x))
    max_err = max(max_err, abs(lhs - rhs_c(math.cos(2 * x))))
print(f"TRIG IDENTITY SAMPLED (2001 points) max error = {max_err:.3e}",
      "PASS" if max_err < 1e-9 else "FAIL")

# 3) Exact root finding for each cubic: rational root theorem + deflation,
#    then the exact quadratic remainder.
def divisors(n):
    n = abs(n)
    return [d for d in range(1, n + 1) if n % d == 0]

def cubic_roots(co):
    ints = [int(a) for a in co]
    p = [F(a) for a in co]
    roots = []
    cands = set()
    for pn in divisors(ints[-1]):
        for q in divisors(ints[0]):
            for s in (1, -1):
                cands.add(F(s * pn, q))
    for r in sorted(cands):
        while len(p) > 1 and poly_eval(p, r) == 0:
            roots.append(r)
            new = [p[0]]
            for a in p[1:-1]:
                new.append(a + r * new[-1])
            p = new
    if len(p) == 3:
        a, b, c = p
        disc = b * b - 4 * a * c
        if disc == 0:
            roots.append(-b / (2 * a))
        elif disc > 0:
            sq = math.sqrt(float(disc))
            roots.append((-float(b) + sq) / (2 * float(a)))
            roots.append((-float(b) - sq) / (2 * float(a)))
    elif len(p) == 2:
        roots.append(-p[1] / p[0])
    return roots

found = []  # (case name, value, exact?)
for name, sgn, lo, hi, co in CASES:
    for r in cubic_roots(co):
        if isinstance(r, F):
            if lo <= r <= hi:
                found.append((name, float(r), True))
        else:
            if float(lo) - 1e-12 <= r <= float(hi) + 1e-12:
                found.append((name, r, False))

# Deduplicate c-values.
uniq = []
for name, val, ex in found:
    if not any(abs(val - u[1]) < 1e-12 for u in uniq):
        uniq.append((name, val, ex))

# 4) Map each c-root to x and verify with the original equation.
def residual(x):
    c2 = math.cos(2 * x)
    return abs((7 / 4 - 2 * c2) * abs(2 * c2 + 1) - math.cos(x) * (math.cos(x) - math.cos(5 * x)))

def in_submitted(x):
