    r = x % math.pi
    return min(abs(r - math.pi / 6), abs(r - 5 * math.pi / 6)) < 1e-9

print("\nCOMPLETE SOLUTION SET (c = cos2x roots, exact enumeration):")
all_residuals_ok = True
missing = []
for name, val, ex in sorted(uniq, key=lambda t: t[1]):
    x0 = math.acos(max(-1.0, min(1.0, val))) / 2  # representative
    res = residual(x0)
    if res > 1e-9:
