    if not (in_submitted(x0) and in_submitted(-x0)):
        missing.append((val, x0))

# 5) Check the submitted answer directly.
print("\nSUBMITTED ANSWER CHECK:")
for xs, label in [(math.pi / 6, "x = pi/6"), (-math.pi / 6, "x = -pi/6"),
                  (math.pi / 3, "x = pi/3 (not in submitted set)")]:
    print(f"  {label}: residual = {residual(xs):.3e}, in submitted family = {in_submitted(xs)}")

sub_valid = residual(math.pi / 6) < 1e-9 and residual(-math.pi / 6) < 1e-9
print("  submitted members are genuine solutions:", "PASS" if sub_valid else "FAIL")

# 6) Verdict.
print()
if missing:
    for val, x0 in missing:
        print(f"MISSING: c=cos2x={val:+.1f}, x = ±{x0/math.pi:.6f}*pi + k*pi satisfies the equation")
    print("CHECK FAIL: submitted answer omits x = ±pi/3 + k*pi (cos2x = -1/2); it is incomplete.")
elif all_residuals_ok and sub_valid:
