from fractions import Fraction as F

# Exact polynomial helpers (coefficients low-to-high, Fraction entries).

def norm(p):
    p = list(p)
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p if p else [F(0)]

def is_zero(p):
    return len(p) == 1 and p[0] == 0

def padd(a, b):
    n = max(len(a), len(b))
    return norm([(a[i] if i < len(a) else F(0)) + (b[i] if i < len(b) else F(0)) for i in range(n)])

def pneg(a):
    return [-c for c in a]

def pmul(a, b):
    r = [F(0)] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            r[i + j] += x * y
    return norm(r)

def pscale(c, a):
    return norm([c * x for x in a])

def pdivmod(a, b):
    a = norm(a)
    b = norm(b)
    if is_zero(b):
        raise ZeroDivisionError
    q = [F(0)] * max(1, len(a) - len(b) + 1)
    r = list(a)
    while not is_zero(r) and len(r) >= len(b):
        k = len(r) - len(b)
        c = r[-1] / b[-1]
        q[k] = c
        for i, bc in enumerate(b):
            r[i + k] -= c * bc
        r.pop()
        r = norm(r) if r else [F(0)]
    return norm(q), norm(r)

def deriv(p):
    if len(p) == 1:
        return [F(0)]
    return norm([i * p[i] for i in range(1, len(p))])

def peval(p, x):
    acc = F(0)
    for c in reversed(p):
        acc = acc * x + c
    return acc

def sturm_sequence(p):
    seq = [norm(p), norm(deriv(p))]
    while True:
        _, r = pdivmod(seq[-2], seq[-1])
        if is_zero(r):
            break
        seq.append(pneg(r))
    return seq

def sign_changes(signs):
    s = [x for x in signs if x != 0]
    return sum(1 for i in range(len(s) - 1) if s[i] != s[i + 1])

def variations(seq, at_pos_inf):
    signs = []
    for s in seq:
        d = len(s) - 1
        sg = 1 if s[-1] > 0 else -1
        if not at_pos_inf and d % 2 == 1:
            sg = -sg
        signs.append(sg)
    return sign_changes(signs)

def count_distinct_real_roots(p):
    # Sturm's theorem: exact count of distinct real roots.
    seq = sturm_sequence(p)
    return variations(seq, at_pos_inf=False) - variations(seq, at_pos_inf=True)

# The map f(t) = 2t^2/(1+t^2), applied as rational functions.
# If g = Gn/Gd then f(g) = 2*Gn^2 / (Gd^2 + Gn^2).
# Denominators are sums of squares built from 1 + t^2, so they never vanish
# at a real point where both Gd and Gn are zero; hence no spurious roots arise.

def f_step(g):
    Gn, Gd = g
    num = pscale(F(2), pmul(Gn, Gn))
    den = padd(pmul(Gd, Gd), pmul(Gn, Gn))
    return (num, den)

ident = ([F(0), F(1)], [F(1)])   # x = x / 1
g3 = f_step(f_step(f_step(ident)))  # f(f(f(x))) as Gn/Gd

# Fixed-point polynomial for x1 = f(f(f(x1))):  x*Gd3(x) - Gn3(x) = 0
P = padd(pmul([F(0), F(1)], g3[1]), pneg(g3[0]))
print("Degree of fixed-point polynomial P:", len(P) - 1)
assert not is_zero(P), "P is identically zero; reduction invalid"

# Exact count of distinct real roots of P.
# Each real root x1 determines x2 = f(x1), x3 = f(x2) uniquely, so the
# number of distinct real x1 values equals the number of real solutions.
n_roots = count_distinct_real_roots(P)
print("Distinct real roots of P (Sturm, exact):", n_roots)

def f(t):
    return F(2) * t * t / (1 + t * t)

# Verify candidate roots exactly by substitution into the original system.
candidates = [F(0), F(1)]
solutions = []
for x1 in candidates:
    x2 = f(x1)
    x3 = f(x2)
    ok = (f(x1) == x2) and (f(x2) == x3) and (f(x3) == x1) and peval(P, x1) == 0
    print(f"candidate x1={x1}: (x1,x2,x3)=({x1},{x2},{x3}) substitution valid: {ok}")
    if ok:
        solutions.append((x1, x2, x3))

print("Verified distinct solutions:", solutions)
print("Number of verified solutions:", len(solutions))
print("Exact count of real solutions (Sturm):", n_roots)

complete = (n_roots == len(solutions))
print("Set of solutions is complete:", complete)

claimed = 1
computed = n_roots if complete else None

if computed is None:
    print("CHECK UNKNOWN")
elif claimed == computed:
    print("CHECK PASS")
else:
