INPUT = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
SUBMITTED = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ] ) ] ) ]"

CLOSER_TO_OPENER = {')': '(', ']': '[', '}': '{', '>': '<'}
OPENER_TO_CLOSER = {v: k for k, v in CLOSER_TO_OPENER.items()}


def scan(tokens):
    """Exact stack scan. Returns (status, stack, index).
    status: True = all closers matched so far, False = mismatch/unmatched closer at index,
            None = unknown token at index."""
    stack = []
    for i, tok in enumerate(tokens):
        if tok in OPENER_TO_CLOSER:
            stack.append(tok)
        elif tok in CLOSER_TO_OPENER:
            if not stack or stack[-1] != CLOSER_TO_OPENER[tok]:
                return False, stack, i
            stack.pop()
        else:
            return None, stack, i
    return True, stack, len(tokens)


def main():
    tin = INPUT.split()
    tsub = SUBMITTED.split()

    status_in, stack_in, idx_in = scan(tin)
    if status_in is not True:
        print("UNSUPPORTED: input prefix is already invalid at index", idx_in)
        return

    # Forced completion: the open brackets left on the stack must be closed in LIFO order.
    expected_suffix = [OPENER_TO_CLOSER[o] for o in reversed(stack_in)]
    print("input open stack (bottom->top):", " ".join(stack_in))
    print("expected suffix:", " ".join(expected_suffix))

    # Submitted answer must preserve the prefix exactly.
    if tsub[:len(tin)] != tin:
        print("prefix altered: CHECK FAIL")
