    return GRAVE in s

# Initial correspondences: voiced stop *d -> t, *b -> p, *j -> c
init_map = {}
for p, r in pairs:
    if r is None:
        continue
    pi, ri = p[1], strip_tone(r)[0]
    init_map.setdefault(pi, set()).add(ri)

