vowel_ə = {"a" for p, r in pairs if p == "*bəsey" and r and "a" in strip_tone(r)[:3]}

# Medial consonant: intervocalic *b -> p (from *bubah -> papàh)
medial_b = {strip_tone(r)[1] for p, r in pairs if p == "*bubah" and r}

# Final open syllable with *-a after a sonorant: grave tone (from *bara->pirà, *bala->pilà)
grave_evidence = [(p, r) for p, r in pairs
                  if p in ("*bara", "*bala") and r and has_grave(r)]
grave_final = len(grave_evidence) > 0

