from fractions import Fraction

E = math.exp

# Candidate parametrizations (tau = t, parameter = s)
OPTS = {
    "1": ("x=3τ(e^s-1), y=τ/2(e^-s+1), u=τ²e^(-2s)",
          lambda t, s: (3*t*(E(s)-1), t/2*(E(-s)+1), t*t*E(-2*s))),
    "2": ("x=2τ(e^s-1), y=τ(2e^(2s)-1), u=τ²/2(1+e^(-2s))",
          lambda t, s: (2*t*(E(s)-1), t*(2*E(2*s)-1), t*t/2*(1+E(-2*s)))),
    "3": ("x=2τ(e^s-1), y=τ/2(e^s+1), u=τ²e^(2s)",
          lambda t, s: (2*t*(E(s)-1), t/2*(E(s)+1), t*t*E(2*s))),
    "4": ("x=τ(e^-s-1), y=-2τ(e^-s-3/2), u=τ²(2e^(-2s)-1)",
          lambda t, s: (t*(E(-s)-1), -2*t*(E(-s)-1.5), t*t*(2*E(-2*s)-1))),
}

# ---- Charpit derivation for F = p*q - u (independent of the options) ----
# Charpit ODEs: x' = F_p = q, y' = F_q = p, u' = pF_p + qF_q = 2pq = 2u,
#               p' = -(F_x + pF_u) = p, q' = -(F_y + qF_u) = q.
# Strip x=0, y=tau, u=tau^2: q0 = du/dtau = 2*tau, p0 = u0/q0 = tau/2 (from pq=u).
def strip_p0(t):
    return Fraction(1, 2) * Fraction(t) if t else Fraction(0)

def strip_q0(t):
    return 2 * Fraction(t)

def expected(t, s):
    # Solve ODEs: p=p0 e^s, q=q0 e^s, u=u0 e^{2s}; integrate x and y with x(0)=0, y(0)=t
    p0, q0 = float(strip_p0(t)), float(strip_q0(t))
    return (q0*(E(s)-1), t + p0*(E(s)-1), t*t*E(2*s))

TAUS = [-1.3, -0.5, 0.4, 1.0, 2.2]
SS = [-0.7, -0.2, 0.0, 0.4, 1.1]
H = 1e-5
H2 = 1e-3
TOL = 1e-4

def close(a, b, tol=TOL):
    return abs(a - b) <= tol * (1.0 + abs(b))

def ds(f, t, s, h=H):
    a, b = f(t, s + h), f(t, s - h)
    return tuple((u - v) / (2*h) for u, v in zip(a, b))

def dt(f, t, s, h=H):
    a, b = f(t + h, s), f(t - h, s)
    return tuple((u - v) / (2*h) for u, v in zip(a, b))

def check(f):
    res = {"initial": True, "match_charpit": True, "pde": True,
           "u_s_eq_2u": True, "charpit_odes": True}
    # Initial curve x=0, y=tau, u=tau^2 at s=0
    for t in TAUS:
        x0, y0, u0 = f(t, 0.0)
        if not (close(x0, 0.0, 1e-9) and close(y0, t) and close(u0, t*t)):
            res["initial"] = False
    for t in TAUS:
        for s in SS:
            # Match against independently derived Charpit solution
            if not all(close(a, b) for a, b in zip(f(t, s), expected(t, s))):
                res["match_charpit"] = False
            xs, ys, us = ds(f, t, s)
            q, p = xs, ys            # x_s = F_p = q, y_s = F_q = p
            u = f(t, s)[2]
            if not close(p*q, u):    # PDE: p*q - u = 0
                res["pde"] = False
            if not close(us, 2*p*q): # u_s = 2pq = 2u
                res["u_s_eq_2u"] = False
    # Charpit ODEs p' = p, q' = q along each characteristic
    for t in TAUS:
        for s in SS:
            def P(sv):
                return ds(f, t, sv)[1]
            def Q(sv):
                return ds(f, t, sv)[0]
            dp = (P(s + H2) - P(s - H2)) / (2*H2)
            dq = (Q(s + H2) - Q(s - H2)) / (2*H2)
            if not (close(dp, P(s), 1e-3) and close(dq, Q(s), 1e-3)):
                res["charpit_odes"] = False
    return res

report = {k: check(v[1]) for k, v in OPTS.items()}
valid = [k for k, r in report.items() if all(r.values())]

if len(valid) == 1:
    k = valid[0]
    answer = f"Option {k}: {OPTS[k][0]}"
else:
    answer = "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "charpit_strip": {"p0": "tau/2", "q0": "2*tau", "u_ode": "u'=2u"},
        "valid_options": valid,
        "checks": report,
    }
}))
