import itertools

# Exhaustive finite-model check. A counterexample (premises true, conclusion false)
# is decisive for invalidity. Absence of one within the bound is only bounded
# evidence of validity, not a proof.
MAX_N = 3


def ex(n, f):
    return any(f(x) for x in range(n))


def subsets_of(n):
    for mask in range(1 << n):
        yield frozenset(i for i in range(n) if (mask >> i) & 1)


def search(prem, concl, preds, max_n=MAX_N):
    """Return the first (n, model) where premise is true and conclusion false."""
    for n in range(1, max_n + 1):
        for combo in itertools.product(list(subsets_of(n)), repeat=len(preds)):
            m = dict(zip(preds, combo))
            if prem(m, n) and not concl(m, n):
                return n, {k: sorted(v) for k, v in m.items()}
    return None


def mismatch_count(prem, concl, preds, max_n=MAX_N):
    """Count models where premise and conclusion differ (checks equivalence)."""
    bad = 0
    total = 0
    for n in range(1, max_n + 1):
        for combo in itertools.product(list(subsets_of(n)), repeat=len(preds)):
            m = dict(zip(preds, combo))
            total += 1
            if bool(prem(m, n)) != bool(concl(m, n)):
                bad += 1
    return bad, total


# Each entry: (predicates, premise(m, n), conclusion(m, n))
# Premise/conclusion formalised as "some X are not Y" / "not all X are Y".
OPTIONS = {
    # Original: Some good things are not cheap. => Not all cheap things are good.
    "original": (
        ["G", "C"],
        lambda m, n: ex(n, lambda x: x in m["G"] and x not in m["C"]),
        lambda m, n: ex(n, lambda x: x in m["C"] and x not in m["G"]),
    ),
    # A: Not all Hunan people like pepper. => Some pepper lovers are not from Hunan.
    "A": (
        ["H", "P"],
        lambda m, n: ex(n, lambda x: x in m["H"] and x not in m["P"]),
        lambda m, n: ex(n, lambda x: x in m["P"] and x not in m["H"]),
    ),
    # B: Some people are not selfish. => People are not all selfish.
    "B": (
        ["P", "S"],
        lambda m, n: ex(n, lambda x: x in m["P"] and x not in m["S"]),
        lambda m, n: ex(n, lambda x: x in m["P"] and x not in m["S"]),
    ),
    # C: A good motive need not have a good effect. => Good results need not come from good motives.
    "C": (
        ["M", "E"],
        lambda m, n: ex(n, lambda x: x in m["M"] and x not in m["E"]),
        lambda m, n: ex(n, lambda x: x in m["E"] and x not in m["M"]),
    ),
    # D: Some southerners are not Cantonese. => Not all Cantonese are southerners.
    "D": (
        ["S", "C"],
        lambda m, n: ex(n, lambda x: x in m["S"] and x not in m["C"]),
        lambda m, n: ex(n, lambda x: x in m["C"] and x not in m["S"]),
    ),
}

