for name, (preds, prem, concl) in OPTIONS.items():
    ce = search(prem, concl, preds)
    results[name] = ce
    if ce is None:
        bad, total = mismatch_count(prem, concl, preds)
        print(f"{name}: no counterexample up to n={MAX_N} "
              f"(bounded sample, {total} models); premise/conclusion mismatches={bad}")
    else:
