            if cmd == "Z" and cur is not None and start is not None and cur != start:
                segs.append((cur, start))
                cur = start
            continue
        x, y = float(toks[i]), float(toks[i + 1])
        i += 2
        p = (x, y)
        if cmd == "M":
            cur = start = p
            cmd = "L"
        elif cmd == "L" and cur is not None:
