        e1 = sub(P[k], P[k - 1])
        e2 = sub(P[(k + 1) % n], P[k])
        cr.append(cross(e1[0], e1[1], e2[0], e2[1]))
    convex = all(c > 0 for c in cr)
    labs = set()
    info = {"n": n, "convex": convex, "sides": [round(s, 5) for s in sides]}

    def par(u, v):
        return abs(cross(u[0], u[1], v[0], v[1])) / (norm(u) * norm(v)) < ANG_TOL

    def regular():
        if not convex:
            return False
        m = sum(sides) / n
        if max(abs(s - m) for s in sides) > LEN_TOL:
            return False
        target = (n - 2) * 180.0 / n
        for k in range(n):
            c = angle_cos(P[k - 1], P[k], P[(k + 1) % n])
            ang = math.degrees(math.acos(max(-1.0, min(1.0, c))))
            if abs(ang - target) > DEG_TOL:
                return False
        return True

    if n == 3:
        mc = min(abs(angle_cos(P[(k - 1) % 3], P[k], P[(k + 1) % 3])) for k in range(3))
        info["min_abs_cos"] = mc
        labs.add(4 if mc < ANG_TOL else 3)
    elif n == 4:
        p1 = par(sub(P[1], P[0]), sub(P[2], P[3]))
        p2 = par(sub(P[2], P[1]), sub(P[3], P[0]))
        rc = abs(angle_cos(P[3], P[0], P[1]))
        info["pair_AB_CD_parallel"] = p1
        info["pair_BC_DA_parallel"] = p2
        info["abs_cos_corner0"] = rc
        if p1 and p2:
            if rc < ANG_TOL:
                labs.add(2 if abs(sides[0] - sides[1]) < LEN_TOL else 1)
            else:
                labs.add(5)
        elif p1 or p2:
            labs.add(6)
    elif n == 5:
        if not convex:
            labs.add(8)
        elif regular():
            labs.add(9)
        else:
            labs.add(7)
    elif n == 6:
        if regular():
            labs.add(10)
    return labs, info


# ---- parse the path into segments (exact decimal -> float) ----
segs = []
for sub_path in PATH.split("M")[1:]:
    pts = [(float(a), float(b)) for a, b in
           re.findall(r"(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)", sub_path)]
    for k in range(len(pts) - 1):
        segs.append((pts[k], pts[k + 1]))
print("segments parsed:", len(segs))

# ---- planar arrangement: endpoints + all pairwise intersections ----
cands = []
for a, b in segs:
    cands.append(a)
    cands.append(b)
for i in range(len(segs)):
    for j in range(i + 1, len(segs)):
        x = seg_hit(segs[i][0], segs[i][1], segs[j][0], segs[j][1])
        if x is not None:
            cands.append(x)

verts = []


def vid_of(p):
    for k, q in enumerate(verts):
        if dist(p, q) < TOL:
            return k
    verts.append(p)
    return len(verts) - 1


for p in cands:
    vid_of(p)

edges = set()
for a, b in segs:
    on = []
    for k, p in enumerate(verts):
        t, d = proj_dist(p, a, b)
        if d < TOL:
            on.append((t, k))
    on.sort()
    for (t1, k1), (t2, k2) in zip(on, on[1:]):
        if k1 != k2:
            edges.add((min(k1, k2), max(k1, k2)))

print("arrangement vertices:", len(verts), " edges:", len(edges))

nb = {k: [] for k in range(len(verts))}
for k1, k2 in edges:
    nb[k1].append(k2)
    nb[k2].append(k1)
for k in nb:
    nb[k].sort(key=lambda w: math.atan2(verts[w][1] - verts[k][1],
                                        verts[w][0] - verts[k][0]))

# ---- half-edge face traversal ----
darts = []
for a, b in edges:
    darts.append((a, b))
    darts.append((b, a))
seen = set()
raw = []
for d0 in darts:
    if d0 in seen:
        continue
    cyc = []
    cur = d0
    while cur not in seen:
        seen.add(cur)
        a, b = cur
        cyc.append(a)
        nbrs = nb[b]
        i = nbrs.index(a)
        cur = (b, nbrs[(i - 1) % len(nbrs)])
    raw.append(cyc)


def area2(ids):
    s = 0.0
    n = len(ids)
    for k in range(n):
        x1, y1 = verts[ids[k]]
        x2, y2 = verts[ids[(k + 1) % n]]
        s += x1 * y2 - x2 * y1
    return s / 2.0


bounded = []
for cyc in raw:
    if area2(cyc) > 1e-9 and len(set(cyc)) == len(cyc):
        bounded.append(cyc)
print("half-edge cycles:", len(raw), " bounded simple faces:", len(bounded))

# ---- classify each bounded face, and verify it has no interior drawn line ----
all_labels = set()
all_chord_free = True
for idx, cyc in enumerate(bounded, 1):
    P = reduce_poly([verts[k] for k in cyc])
    chords = 0
    for k1, k2 in edges:
        a, b = verts[k1], verts[k2]
        for f in (0.25, 0.5, 0.75):
            pt = (a[0] + f * (b[0] - a[0]), a[1] + f * (b[1] - a[1]))
            if bdist(pt, P) > TOL and inside(pt, P):
                chords += 1
                break
    if chords:
        all_chord_free = False
    labs, info = classify(P)
    all_labels |= labs
    coords = ["(%.5f, %.5f)" % p for p in P]
    print("face %d: vertices=%s" % (idx, " ".join(coords)))
    print("   info=%s chords_inside=%d labels=%s" % (info, chords, sorted(labs)))

expected = OPTIONS[SELECTED]
matches = [k for k, v in OPTIONS.items() if v == all_labels]
print("derived shape labels:", sorted(all_labels))
print("selected option", SELECTED, "content:", sorted(expected))
print("options whose content equals derived labels:", matches)

if not bounded:
    print("CHECK UNKNOWN")
elif all_labels == expected and all_chord_free:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
