    "L": {1, 2, 5, 10}, "M": {1, 2, 8, 9}, "N": {2, 7}, "O": {2, 3, 6},
    "P": {1, 2, 6, 10},
}
SUBMITTED = "F"


def norm(v):
    r = round(v, 4)
    return 0.0 if r == 0 else r


def parse_path(d):
    num = r'([-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?)'
    segs, cur = [], None
    for m in re.finditer(r'([ML])\s*' + num + r'\s*,\s*' + num, d):
        p = (norm(float(m.group(2))), norm(float(m.group(3))))
        if m.group(1) == 'M':
            cur = p
        else:
            segs.append((cur, p))
            cur = p
    return segs


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def length(a):
    return math.hypot(a[0], a[1])


def close(a, b):
    return abs(a[0] - b[0]) < TOL and abs(a[1] - b[1]) < TOL


def seg_intersection(a, b, c, d):
    r, s = sub(b, a), sub(d, c)
    den = cross(r, s)
    if abs(den) < 1e-12:
        return None
    ca = sub(c, a)
    t = cross(ca, s) / den
    u = cross(ca, r) / den
    if -1e-9 <= t <= 1 + 1e-9 and -1e-9 <= u <= 1 + 1e-9:
        return (a[0] + t * r[0], a[1] + t * r[1])
    return None


def point_on_seg(p, a, b):
    r = sub(b, a)
