    if abs(cross(sub(p, a), r)) / L > TOL:
        return False
    t = dot(sub(p, a), r) / (L * L)
    return -TOL / L <= t <= 1 + TOL / L


def inside(p, poly):
    n = len(poly)
    for i in range(n):
        if point_on_seg(p, poly[i], poly[(i + 1) % n]):
            return False  # boundary point, not strictly inside
    c = False
    for i in range(n):
        a, b = poly[i], poly[(i + 1) % n]
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if p[0] < x:
