    on.sort(key=lambda k: dot(sub(pts[k], a), r))
    for u, v in zip(on, on[1:]):
        if u != v:
            edges.add(frozenset((u, v)))

adj = {k: set() for k in range(len(pts))}
for e in edges:
    u, v = tuple(e)
    adj[u].add(v)
    adj[v].add(u)

print("drawn nodes:", len(pts), "sub-edges:", len(edges))

# ---- exhaustive enumeration of simple cycles (candidate outer boundaries) ----
cycles = {}


def dfs(start, cur, path, visited):
    for nb in adj[cur]:
