                            for i in range(len(path)))
            if key not in cycles:
                cycles[key] = list(path)
        elif nb > start and nb not in visited:
            visited.add(nb)
            path.append(nb)
            dfs(start, nb, path, visited)
            path.pop()
            visited.discard(nb)


for s in range(len(pts)):
    dfs(s, s, [s], {s})

print("simple cycles enumerated:", len(cycles))

# ---- analyse each cycle as a polygon ----
found_clean = set()
found_internal = set()

for key, path in cycles.items():
    poly_all = [pts[k] for k in path]
    n_all = len(poly_all)

    corners = []
    for i in range(n_all):
        prev, cur, nxt = poly_all[i - 1], poly_all[i], poly_all[(i + 1) % n_all]
        e1, e2 = sub(cur, prev), sub(nxt, cur)
        l1, l2 = length(e1), length(e2)
        if l1 < 1e-9 or l2 < 1e-9:
