    orient = 1 if area2 > 0 else -1

    turns, angs, sides = [], [], []
    for i in range(m):
        prev, cur, nxt = corners[i - 1], corners[i], corners[(i + 1) % m]
        e_in, e_out = sub(cur, prev), sub(nxt, cur)
        turns.append(orient * cross(e_in, e_out))
        u, v = sub(prev, cur), sub(nxt, cur)
        c = max(-1.0, min(1.0, dot(u, v) / (length(u) * length(v))))
        ang = math.degrees(math.acos(c))
        angs.append(ang if turns[-1] > 0 else 360.0 - ang)
        sides.append(length(e_out))
    concave = any(t < -1e-9 for t in turns)
    convex = not concave

    internal = []
    for e in edges:
        if e in key:
            continue
        u, v = tuple(e)
        mid = ((pts[u][0] + pts[v][0]) / 2, (pts[u][1] + pts[v][1]) / 2)
        if inside(mid, poly_all):
            internal.append(e)
    has_internal = len(internal) > 0

    s = [sub(corners[(i + 1) % m], corners[i]) for i in range(m)]
    labels = []
    if m == 3:
        right = any(abs(a - 90) < 0.05 for a in angs)
        labels.append(4 if right else 3)
    elif m == 4 and convex:
        p02 = abs(cross(s[0], s[2])) / (length(s[0]) * length(s[2])) < 1e-3
        p13 = abs(cross(s[1], s[3])) / (length(s[1]) * length(s[3])) < 1e-3
        npar = int(p02) + int(p13)
        all_right = all(abs(a - 90) < 0.05 for a in angs)
        if npar == 2:
            if all_right:
                if abs(sides[0] - sides[1]) < 1e-2:
                    labels.append(2)
                else:
                    labels.append(1)
            else:
                labels.append(5)
        elif npar == 1:
            labels.append(6)
    elif m == 5:
        eq_sides = max(sides) - min(sides) < 5e-3
        eq_angs = max(angs) - min(angs) < 0.1
        if convex and eq_sides and eq_angs:
            labels.append(9)
        elif convex:
            labels.append(7)
        else:
            labels.append(8)
    elif m == 6 and convex:
        if max(sides) - min(sides) < 5e-3 and max(angs) - min(angs) < 0.1:
            labels.append(10)

    for lab in labels:
        if has_internal:
            found_internal.add(lab)
        else:
            found_clean.add(lab)
        print(f"shape {lab}: corners={m} concave={concave} "
              f"internal_edges={len(internal)} "
              f"vertices={[(round(c[0],3), round(c[1],3)) for c in corners]}")

print("labels with internal diagonals (not valid for 'no diagonals'):", sorted(found_internal))
print("viewable shape numbers (no internal lines):", sorted(found_clean))

found = found_clean
matches = [k for k, v in OPTIONS.items() if v == found]
print("options whose content equals the found set:", matches)
print("submitted option", SUBMITTED, "content:", sorted(OPTIONS[SUBMITTED]))

if found == OPTIONS[SUBMITTED]:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
