    primary_card = {"basenji": False}  # violet card is not red, green or blue
    negotiates = {("goat", "pigeon")}
    trades = {("monkey", "goat")}

    # Rule1 and Rule2: sharp object or primary-color card -> does not disarm the dove
    not_disarm_dove = {"basenji": sharp.get("basenji", False) or primary_card.get("basenji", False)}

    # Rule8: does not disarm the dove -> wants to see the reindeer
    wants_reindeer = {"basenji": not_disarm_dove["basenji"]}

    # Rule6 (preferred over Rule3) and Rule3: neglect the goose for the goat
    r6_fires = (not beetle_leaves_goat_houses) and (("monkey", "goat") in trades)
    r3_fires = ("goat", "pigeon") in negotiates
    if r6_fires:
        goat_neglects_goose = True           # Rule6 wins over Rule3
    elif r3_fires:
        goat_neglects_goose = False          # Rule3: never neglects the goose
    else:
        goat_neglects_goose = False          # no rule concludes neglect (closed world)
    neglects_goose = {"goat": goat_neglects_goose, "basenji": False}

    # Rule5: does not neglect the goose -> surrenders to the chinchilla
    surrenders_chinchilla = {a: not neglects_goose[a] for a in neglects_goose}

    # Rule4: at least one animal surrenders to the chinchilla -> basenji hides cards from songbird
    r4_fires = any(surrenders_chinchilla.values())

