        if 0 < t < 1:
            px, py = ka[0] + t * dx, ka[1] + t * dy
            if math.hypot(px - n[0], py - n[1]) < 2e-4:
                inner.append((t, n))
    chain = [ka] + [n for _, n in sorted(inner)] + [kb]
    for u, v in zip(chain, chain[1:]):
