# Trace faces: at each arrival, take the clockwise-next edge. Interior faces get area > 0.
seen = set()
faces = []
for u in adj:
    for v in adj[u]:
        if (u, v) in seen:
            continue
        cyc = []
        a, b = u, v
        while (a, b) not in seen:
            seen.add((a, b))
            cyc.append(a)
            nb = order[b]
            c = nb[(nb.index(a) - 1) % len(nb)]
            a, b = b, c
