    return m["XL"] and not v["XL"]

def B(m, v):  # every Expo volunteer is a member
    return all((not v[x]) or m[x] for x in PEOPLE)

def C(m, v):  # a volunteer-member is not XL
    return all(not (v[x] and m[x]) or x != "XL" for x in PEOPLE)

def D(m, v):  # member but not volunteer implies XL
    return all(not (m[x] and not v[x]) or x == "XL" for x in PEOPLE)

