    segs, cur = [], None
    for cmd, x, y in re.findall(r'([ML])\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)', s):
        p = (Fr(x), Fr(y))
        if cmd == 'M':
            cur = p
        else:
            segs.append((cur, p))
            cur = p
    return [(a, b) for a, b in segs if a != b]


def on_seg(p, a, b):
    if cross(sub(b, a), sub(p, a)) != 0:
        return False
    return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
            min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))


def inter(a, b, c, d):
    r, s = sub(b, a), sub(d, c)
    den = cross(r, s)
    if den == 0:
        return None
    qp = sub(c, a)
    t = cross(qp, s) / den
    u = cross(qp, r) / den
    if 0 <= t <= 1 and 0 <= u <= 1:
        return (a[0] + t * r[0], a[1] + t * r[1])
    return None


def split_all(segs):
    edges = set()
    for i, (a, b) in enumerate(segs):
        pts = {a, b}
        for j, (c, d) in enumerate(segs):
            if i == j:
                continue
            for p in (c, d):
                if on_seg(p, a, b):
                    pts.add(p)
            q = inter(a, b, c, d)
            if q is not None:
                pts.add(q)
        ordered = sorted(pts, key=lambda p: dot(sub(p, a), sub(b, a)))
        for u, v in zip(ordered, ordered[1:]):
            edges.add(tuple(sorted((u, v))))
    return sorted(edges)


segs = parse(PATH)
E = split_all(segs)

adj = {}
for u, v in E:
    adj.setdefault(u, set()).add(v)
    adj.setdefault(v, set()).add(u)

# prune dangling edges (degree-1 vertices) repeatedly
changed = True
while changed:
    changed = False
    for v in list(adj.keys()):
        if v in adj and len(adj[v]) == 1:
            (w,) = tuple(adj[v])
            adj[w].discard(v)
            if not adj[w]:
                del adj[w]
            del adj[v]
            changed = True


def covered(a, b):
    """True if segment ab is fully covered by drawn sub-edges (exact)."""
    d = sub(b, a)
    L = dot(d, d)
    ivs = []
    for p, q in E:
        if cross(d, sub(p, a)) == 0 and cross(d, sub(q, a)) == 0:
            tp = dot(sub(p, a), d) / L
            tq = dot(sub(q, a), d) / L
            lo = max(Fr(0), min(tp, tq))
            hi = min(Fr(1), max(tp, tq))
            if lo < hi:
                ivs.append((lo, hi))
    ivs.sort()
    cur = Fr(0)
    for lo, hi in ivs:
        if lo <= cur:
            cur = max(cur, hi)
    return cur >= 1


def ang(v, w):
    return math.atan2(float(w[1] - v[1]), float(w[0] - v[0]))


order = {v: sorted(adj[v], key=lambda w: ang(v, w)) for v in adj}

seen = set()
faces = []
for v in adj:
    for w in adj[v]:
        if (v, w) in seen:
            continue
        cyc = []
        x, y = v, w
        while (x, y) not in seen:
            seen.add((x, y))
            cyc.append(x)
            nb = order[y]
            z = nb[(nb.index(x) - 1) % len(nb)]
            x, y = y, z
        faces.append(cyc)


def corners_of(cyc):
    pts = list(cyc)
    changed = True
    while changed and len(pts) > 3:
        changed = False
        n = len(pts)
        for i in range(n):
            a, b, c = pts[i - 1], pts[i], pts[(i + 1) % n]
            if cross(sub(b, a), sub(c, b)) == 0:
                pts.pop(i)
                changed = True
                break
    return pts


def describe(C):
    n = len(C)
    Ex = [sub(C[(i + 1) % n], C[i]) for i in range(n)]
    convex = all(cross(Ex[i], Ex[(i + 1) % n]) > 0 for i in range(n))
    ev = [(float(e[0]), float(e[1])) for e in Ex]
    L = [math.hypot(*e) for e in ev]
    cos_v = []
    for i in range(n):
        p, q = ev[i - 1], ev[i]
        cos_v.append(dot(p, q) / (math.hypot(*p) * math.hypot(*q)))
    right_count = sum(1 for c in cos_v if abs(c) < 1e-3)
    angles = [math.acos(max(-1.0, min(1.0, -c))) for c in cos_v]
    equal_sides = (max(L) - min(L)) < 1e-3
    regular = equal_sides and (max(angles) - min(angles)) < 1e-3
    parallel_pairs = 0
    if n == 4:
        for i, j in ((0, 2), (1, 3)):
            u, v = ev[i], ev[j]
            if abs(u[0] * v[1] - u[1] * v[0]) / (L[i] * L[j]) < 1e-3:
                parallel_pairs += 1
    rectangle = (n == 4 and right_count == 4)
    square = rectangle and equal_sides
    parallelogram = (n == 4 and parallel_pairs == 2)
    diag_drawn = False
    for i in range(n):
        for j in range(i + 2, n):
            if i == 0 and j == n - 1:
                continue
            if covered(C[i], C[j]):
                diag_drawn = True
    return {"n": n, "convex": convex, "regular": regular, "equal_sides": equal_sides,
            "right_count": right_count, "rectangle": rectangle, "square": square,
            "parallelogram": parallelogram, "parallel_pairs": parallel_pairs,
            "diag_drawn": diag_drawn}


def items_of(d):
    res = set()
    n = d["n"]
    nd = not d["diag_drawn"]
    if n == 4 and d["rectangle"] and not d["square"] and nd: res.add(1)
    if n == 4 and d["square"] and nd: res.add(2)
    if n == 3 and d["right_count"] == 0: res.add(3)
    if n == 3 and d["right_count"] > 0: res.add(4)
    if n == 4 and d["parallelogram"] and not d["rectangle"] and nd: res.add(5)
    if n == 4 and d["parallel_pairs"] == 1 and nd: res.add(6)
    if n == 5 and d["convex"] and not d["regular"] and nd: res.add(7)
    if n == 5 and not d["convex"] and not d["regular"] and nd: res.add(8)
    if n == 5 and d["regular"] and nd: res.add(9)
    if n == 6 and d["regular"] and nd: res.add(10)
    return res


face_info = []
viewable = set()
for cyc in faces:
    area2 = sum(cross(cyc[i], cyc[(i + 1) % len(cyc)]) for i in range(len(cyc)))
    if area2 <= 0:
        continue  # outer (unbounded) face
    C = corners_of(cyc)
    d = describe(C)
    its = items_of(d)
    viewable |= its
    face_info.append({"corners": [[float(x), float(y)] for x, y in C], **d, "items": sorted(its)})

OPTIONS = {
    "A": {1, 8, 10}, "B": {8, 2}, "C": {8, 2, 6}, "D": {8, 3, 6}, "E": {8},
    "F": {1, 8}, "H": {1, 5}, "I": {1, 8, 2}, "J": {8, 10}, "K": {1},
    "L": {1, 6, 10}, "M": {8, 3}, "N": {8, 7}, "O": {1, 4, 7, 10}, "P": {6, 10},
}
matches = [k for k, v in OPTIONS.items() if v == viewable]
final = matches[0] if matches else "G"
label = "none of the above" if final == "G" else ", ".join(str(i) for i in sorted(OPTIONS[final]))

print(json.dumps({
    "final_answer": f"({final}) {label}",
    "viewable_items": sorted(viewable),
    "matched_option": final if matches else None,
    "bounded_faces": face_info,
}))
