from itertools import product

# Atoms: T=flamingo trades with songbird, D=dugong trades with songbird,
# I=songbird has internet-connecting device, S=songbird smiles at crab,
# F=some animal leaves houses occupied by finch, B=crab swears to beetle.
# Given facts: T=True. "songbird has a computer" is not used by any rule.
# Only T is asserted; all other atoms are free unless a rule forces them.

def consistent(T, D, I, S, F, B):
    if not T:
        return False  # given fact
    r1_fires = T and D                      # Rule1: concludes NOT smiling at crab
    if r1_fires and S:
        return False                        # Rule1 overrides Rule3
    if I and not r1_fires and not S:
        return False                        # Rule3: internet device -> smiles (not defeated)
    r4_fires = F                            # Rule4: finch-house leaver -> swears to beetle
    if F and not B:
        return False                        # Rule4 applies
    if S and not F and B:
        return False                        # Rule2: smiles -> NOT swears (Rule4 overrides Rule2 only when it fires)
    if S and not F and B:
        return False
    if S and F and B:
        return True                         # Rule4 overrides Rule2, so B allowed
    return True

models = [m for m in product([True, False], repeat=6) if consistent(*m)]
b_true = [m for m in models if m[5]]
b_false = [m for m in models if not m[5]]

print("consistent models:", len(models))
print("models with crab swears to beetle:", len(b_true))
print("models with crab does NOT swear to beetle:", len(b_false))

if b_true and b_false:
    print("B is not forced by the facts and rules -> answer is unknown")
    print("Claimed answer 'Proven: crab does not swear to beetle' is not entailed")
    print("CHECK FAIL")
elif b_false and not b_true:
    print("CHECK PASS")
elif b_true and not b_false:
    print("CHECK FAIL")
else:
    print("UNSUPPORTED")
```

