def inv2(M):
    (a, b), (c, d) = M
    det = a * d - b * c
    if det == 0:
        raise ValueError("singular")
    return [[d / det, -b / det], [-c / det, a / det]]

def add_identity(M):
    return [[M[0][0] + 1, M[0][1]], [M[1][0], M[1][1] + 1]]

