def rhs_t(t):
    # t = cos 2x. cos^2 x = (1+t)/2; cos x cos 5x = (cos 4x + cos 6x)/2
    cos2x_sq = (1 + t) / 2
    cos4x = 2 * t * t - 1
    cos6x = 4 * t ** 3 - 3 * t
    return cos2x_sq - (cos4x + cos6x) / 2

# 1) Exhaustive enumeration of rational t = p/q in [-1, 1], q <= 120
rat = set()
for q in range(1, 121):
    for p in range(-q, q + 1):
        t = F(p, q)
        if lhs_t(t) == rhs_t(t):
            rat.add(t)
rat = sorted(rat)

# 2) Independent float scan using the direct trig form in x (no polynomial reduction)
def g(t):
    x = math.acos(max(-1.0, min(1.0, t))) / 2
    c2, c1, c5 = math.cos(2 * x), math.cos(x), math.cos(5 * x)
    return (7 / 4 - 2 * c2) * abs(2 * c2 + 1) - c1 * (c1 - c5)

N = 40000
grid = [-1 + 2 * i / N for i in range(N + 1)]
num_roots = []
for a, b in zip(grid, grid[1:]):
    ga, gb = g(a), g(b)
    if abs(ga) < 1e-9:
        num_roots.append(a)
    elif ga * gb < 0:
        lo, hi = a, b
        for _ in range(100):
