import json
from fractions import Fraction as F

def member(a, b, c, x):
    # Membership in the solution set of a*x^2 + b*x + c <= 0
    return a * x * x + b * x + c <= 0

def target(x):
    # Given solution set: x <= -1 or x >= 3
    return x <= -1 or x >= 3

def exact_sqrt(q):
    # Exact square root of a non-negative Fraction, or None if irrational
    if q < 0:
        return None
    import math
    n, d = q.numerator, q.denominator
    rn, rd = math.isqrt(n), math.isqrt(d)
    if rn * rn == n and rd * rd == d:
        return F(rn, rd)
    return None

grid = [F(k, 4) for k in range(-60, 61)]

# Step 1: enumerate candidate (a, b, c) that reproduce the given solution set
cands = []
for a in [F(-1), F(-2), F(-3), F(-1, 2), F(-3, 2)]:
    for b in range(-12, 13):
        for c in range(-12, 13):
            A, B, C = a, F(b), F(c)
            if all(member(A, B, C, x) == target(x) for x in grid):
                cands.append((A, B, C))

# Step 2: for each candidate, solve c*x^2 - b*x + a < 0 exactly via its roots
answers = set()
evidence = []
for A, B, C in cands:
    if C == 0:
        continue
    D = B * B - 4 * C * A
    s = exact_sqrt(D)
    if s is None:
        continue
    r1 = (-(-B) - s) / (2 * C)
    r2 = (-(-B) + s) / (2 * C)
    lo, hi = min(r1, r2), max(r1, r2)

    # Membership of the quadratic inequality, checked on the grid
    def q_less(x):
        return C * x * x - B * x + A < 0

    if C > 0:
        ans = f"{lo} < x < {hi}"
        ok = all(q_less(x) == (lo < x < hi) for x in grid if x not in (lo, hi))
    else:
        ans = f"x < {lo} or x > {hi}"
        ok = all(q_less(x) == (x < lo or x > hi) for x in grid if x not in (lo, hi))

    if ok:
        answers.add(ans)
        evidence.append({"a": str(A), "b": str(B), "c": str(C),
                         "roots": [str(lo), str(hi)]})

final = answers.pop() if len(answers) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "candidates_checked": len(cands),
        "consistent_answers": len(evidence),
        "sample": evidence[:2]
    }
}))
