def bisect(a, b):
    fa = h(a)
    for _ in range(200):
        m = (a + b) / 2
        fm = h(m)
        if (fa <= 0) == (fm <= 0):
            a, fa = m, fm
        else:
            b = m
    return (a + b) / 2

def golden_min_abs(a, b):
    g = (5 ** 0.5 - 1) / 2
    c = b - g * (b - a)
    d = a + g * (b - a)
    for _ in range(200):
        if abs(h(c)) < abs(h(d)):
            b = d
        else:
            a = c
        c = b - g * (b - a)
        d = a + g * (b - a)
    return (a + b) / 2

