import itertools
import json

PAIRS = {"(": ")", "[": "]", "{": "}", "<": ">"}
CLOSE_TO_OPEN = {v: k for k, v in PAIRS.items()}
ALPHABET = list(PAIRS) + list(CLOSE_TO_OPEN)
PREFIX = "< { ( { } ) < > }".split()


def reduce_stack(tokens):
    """Return the open-bracket stack after processing tokens, or None if invalid."""
    stack = []
    for t in tokens:
        if t in PAIRS:
            stack.append(t)
        elif t in CLOSE_TO_OPEN:
            if not stack or stack[-1] != CLOSE_TO_OPEN[t]:
                return None
            stack.pop()
        else:
            return None
    return stack


def find_minimal_completions(prefix, max_len=5):
    """Exhaustively search completions by increasing length until balanced ones appear."""
    for length in range(max_len + 1):
        found = []
        for cand in itertools.product(ALPHABET, repeat=length):
            if reduce_stack(prefix + list(cand)) == []:
                found.append(list(cand))
        if found:
            return length, found
    return None, []


base_stack = reduce_stack(PREFIX)

if base_stack is None:
    final_answer = "UNSUPPORTED"
    evidence = {"reason": "input prefix is not a valid bracket prefix"}
else:
    min_len, sols = find_minimal_completions(PREFIX)
    if len(sols) == 1:
        final_answer = " ".join(sols[0])
        evidence = {
            "open_after_prefix": base_stack,
            "min_completion_length": min_len,
