import math
import json

S, Q = 9.0, 14.0
ZMAX = (18.0 + math.sqrt(624.0)) / 6.0  # largest z admitting real x, y (discriminant >= 0)


def F(x, y, z):
    return sum((a * a + b * b) / (a + b) for a, b in ((x, y), (x, z), (y, z)))


def point(z):
    # x + y = S - z, xy = Q - z(S - z); need z > 0, x > 0, y > 0
    s = S - z
    p = Q - z * s
    if z <= 0 or s <= 0 or p <= 0:
        return None
    d = max(0.0, s * s - 4.0 * p)
    r = math.sqrt(d)
    x, y = (s + r) / 2.0, (s - r) / 2.0
    if x <= 0 or y <= 0:
        return None
    return (x, y, z)


N = 400000
