STUDENTS = ["Franz", "Greene", "Hidalgo", "Isaacs"]
PAINTINGS = [(s, t) for s in STUDENTS for t in ("oil", "water")]
SLOTS = [(w, p) for w in (1, 2, 3, 4) for p in ("U", "L")]


def valid_arrangements():
    """Yield every bijection of the 8 paintings onto the 8 wall slots that satisfies the rules."""
    for perm in permutations(range(len(SLOTS))):
        pos = {PAINTINGS[i]: SLOTS[perm[i]] for i in range(len(PAINTINGS))}
        walls = {w: [] for w in (1, 2, 3, 4)}
        for painting, (w, _) in pos.items():
            walls[w].append(painting)

        ok = True
        for w, items in walls.items():
            # No wall has only watercolors.
            if all(t == "water" for _, t in items):
                ok = False
                break
            # No wall has work of only one student.
            if len({s for s, _ in items}) < 2:
                ok = False
                break
            # No wall has both Franz and Isaacs.
            students_here = {s for s, _ in items}
            if "Franz" in students_here and "Isaacs" in students_here:
                ok = False
                break
        if not ok:
            continue

        # Greene's watercolor is in the upper position of the wall holding Franz's oil.
        gw = pos[("Greene", "water")]
        fo = pos[("Franz", "oil")]
        if not (gw[1] == "U" and gw[0] == fo[0]):
            continue

        # Isaacs's oil is in the lower position of wall 4.
        if pos[("Isaacs", "oil")] != (4, "L"):
            continue

        yield pos


def position(pos, painting):
    return pos[painting][1]


OPTIONS = {
    "A": lambda pos: all(position(pos, p) == "L" for p in
                         [("Franz", "oil"), ("Franz", "water"),
                          ("Greene", "oil"), ("Greene", "water")]),
    "B": lambda pos: all(position(pos, p) == "U" for p in
                         [("Franz", "oil"), ("Franz", "water"),
                          ("Greene", "oil"), ("Greene", "water")]),
    "C": lambda pos: all(position(pos, p) == "U" for p in
                         [("Franz", "oil"), ("Franz", "water"),
                          ("Hidalgo", "oil"), ("Hidalgo", "water")]),
    "D": lambda pos: all(position(pos, p) == "L" for p in
                         [("Greene", "oil"), ("Greene", "water"),
                          ("Hidalgo", "oil"), ("Hidalgo", "water")]),
    "E": lambda pos: all(position(pos, p) == "U" for p in
                         [("Greene", "oil"), ("Greene", "water"),
                          ("Hidalgo", "oil"), ("Hidalgo", "water")]),
}


def main():
    arrangements = list(valid_arrangements())
    feasible = {}
    for letter, pred in OPTIONS.items():
        feasible[letter] = sum(1 for pos in arrangements if pred(pos))

    could_be_true = [k for k, v in feasible.items() if v > 0]
    if len(could_be_true) == 1:
        final_answer = could_be_true[0]
    else:
        final_answer = "UNSUPPORTED"

    result = {
        "final_answer": final_answer,
        "evidence": {
            "valid_arrangements": len(arrangements),
            "feasible_counts_per_option": feasible,
            "options_that_could_be_true": could_be_true,
        },
    }
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()
