import json
import math

# Side lengths from the problem: a = |BC|, b = |CA|, c = |AB|.
a, b, c = 4.0, 5.0, math.sqrt(21.0)
dist = {
    frozenset(("B", "C")): a,
    frozenset(("C", "A")): b,
    frozenset(("A", "B")): c,
}

def d(p, q):
    if p == q:
        return 0.0
    return dist[frozenset((p, q))]

options = {
    "A": 5 - math.sqrt(21.0),
    "B": (math.sqrt(21.0) + 5) / 2,
    "C": 5 + math.sqrt(21.0),
    "D": (5 - math.sqrt(21.0)) / 2,
}

vertices = ["A", "B", "C"]
candidates = []
# Search over every choice of two vertices as foci and check the hyperbola constraints.
for i in range(3):
    for j in range(i + 1, 3):
        f1, f2 = vertices[i], vertices[j]
        if "A" in (f1, f2):
            # A is on the curve, so it cannot be a focus (would force e = 1).
            continue
        two_c = d(f1, f2)
        two_a = abs(d("A", f1) - d("A", f2))
        if two_a <= 0 or two_a >= two_c:
            continue
        e = two_c / two_a
        candidates.append({"foci": [f1, f2], "e": e})

matches = []
for label, val in options.items():
    for cand in candidates:
        if math.isclose(cand["e"], val, rel_tol=1e-12, abs_tol=1e-12):
            matches.append(label)

final_answer = matches[0] if len(set(matches)) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "valid_hyperbolas": candidates,
        "matched_options": sorted(set(matches)),
    },
}))
