import json
import math

# Charpit system for F(x,y,u,p,q) = p*q - u = 0:
#   dx/dt = F_p = q,  dy/dt = F_q = p,  du/dt = p*F_p + q*F_q = 2pq = 2u,
#   dp/dt = -F_x - p*F_u = p,  dq/dt = -F_y - q*F_u = q.
# Initial strip: x=0, y=tau, u=tau^2. Then q0 = 2*tau, p0 = tau/2 (from p*q=u and u_tau = q0).

H = 1e-4
TAUS = [0.5, 1.0, -1.5, 2.0]
SS = [0.0, 0.3, 0.7]

OPTIONS = {
    1: (lambda t, s: 3*t*(math.exp(s)-1),
        lambda t, s: t/2*(math.exp(-s)+1),
        lambda t, s: t*t*math.exp(-2*s)),
    2: (lambda t, s: 2*t*(math.exp(s)-1),
        lambda t, s: t*(2*math.exp(2*s)-1),
        lambda t, s: t*t/2*(1+math.exp(-2*s))),
    3: (lambda t, s: 2*t*(math.exp(s)-1),
        lambda t, s: t/2*(math.exp(s)+1),
        lambda t, s: t*t*math.exp(2*s)),
    4: (lambda t, s: t*(math.exp(-s)-1),
        lambda t, s: -2*t*(math.exp(-s)-1.5),
        lambda t, s: t*t*(2*math.exp(-2*s)-1)),
}

def close(a, b, tol=1e-5):
    return abs(a-b) <= tol*(1.0+abs(a)+abs(b))

def d1(f, t, s):
    return (f(t, s+H) - f(t, s-H)) / (2*H)

def d2(f, t, s):
    return (f(t, s+H) - 2*f(t, s) + f(t, s-H)) / (H*H)

def check_option(X, Y, U):
    ok = {"initial": True, "strip": True, "pq_eq_u": True,
          "du_charpit": True, "dp_dq_charpit": True}
    for t in TAUS:
        # initial curve at s=0
        if not (close(X(t, 0.0), 0.0) and close(Y(t, 0.0), t) and close(U(t, 0.0), t*t)):
            ok["initial"] = False
        # strip compatibility: q0 = dX/ds(0) = 2t, p0 = dY/ds(0) with p0*q0 = t^2
        q0 = d1(X, t, 0.0)
        p0 = d1(Y, t, 0.0)
        if not (close(q0, 2*t) and close(p0*q0, t*t)):
            ok["strip"] = False
        # du/dtau at s=0 must equal p0*dx/dtau + q0*dy/dtau
        dU = (U(t+H, 0.0) - U(t-H, 0.0)) / (2*H)
        dX = (X(t+H, 0.0) - X(t-H, 0.0)) / (2*H)
        dY = (Y(t+H, 0.0) - Y(t-H, 0.0)) / (2*H)
        if not close(dU, p0*dX + q0*dY, 1e-4):
            ok["strip"] = False
        for s in SS:
            p = d1(Y, t, s)
            q = d1(X, t, s)
            u = U(t, s)
            if not close(p*q, u, 1e-4):
                ok["pq_eq_u"] = False
            if not close(d1(U, t, s), 2*p*q, 1e-4):
                ok["du_charpit"] = False
            if not (close(d2(Y, t, s), p, 1e-3) and close(d2(X, t, s), q, 1e-3)):
                ok["dp_dq_charpit"] = False
    return ok

evidence = {}
passing = []
for k, (X, Y, U) in OPTIONS.items():
    res = check_option(X, Y, U)
    evidence[str(k)] = res
    if all(res.values()):
        passing.append(k)

if len(passing) == 1:
    final_answer = str(passing[0])
else:
    final_answer = "UNSUPPORTED"

print(json.dumps({"final_answer": final_answer, "evidence": evidence}, separators=(",", ":")))
```

