BANDS = "UVWXYZ"  # U=Uneasy, V=Vegemite, W=Wellspring, X=Xpert, Y=Yardsign, Z=Zircon
SLOTS = range(1, 7)

def base_ok(p):
    # Constraints that stay in force under any substitution
    return p['V'] < p['Z'] and p['U'] in (4, 5, 6) and p['Y'] in (1, 2, 3)

def original_ok(p):
    return base_ok(p) and p['W'] < p['X'] and p['Z'] < p['X']

OPTIONS = {
    "A": lambda p: all(p[b] < p['X'] for b in "VWYZ"),
    "B": lambda p: p['V'] < p['W'] and p['W'] < p['Z'],
    "C": lambda p: p['V'] < p['X'] and p['W'] < p['X'],
    "D": lambda p: abs(p['X'] - p['U']) == 1,
    "E": lambda p: p['X'] in (5, 6),
}

def valid_set(pred):
    found = set()
    for perm in itertools.permutations(SLOTS):
        p = dict(zip(BANDS, perm))
        if pred(p):
            found.add(perm)
    return found

original_set = valid_set(original_ok)

evidence = {"original_valid_count": len(original_set), "option_counts": {}, "matches": []}

for letter, opt in OPTIONS.items():
    sub_set = valid_set(lambda p, o=opt: base_ok(p) and o(p))
    evidence["option_counts"][letter] = len(sub_set)
    if sub_set == original_set:
        evidence["matches"].append(letter)

if len(evidence["matches"]) == 1:
    final = evidence["matches"][0]
elif len(evidence["matches"]) == 0:
    final = "UNSUPPORTED"
else:
    final = "UNSUPPORTED"

print(json.dumps({"final_answer": final, "evidence": evidence}, sort_keys=True))
