            continue
        # Yuki cannot test J (either day)
        if a1['Y'] == 'J' or a2['Y'] == 'J':
            continue
        # Theresa must be a tester for H (on some day)
        if not (a1['T'] == 'H' or a2['T'] == 'H'):
            continue
        # Yuki's day-1 bike must be tested by Seamus on day 2
        if a2['S'] != a1['Y']:
            continue
        solutions.append((a1, a2))

