import json
import itertools
from collections import deque

# Buildings and their classes (1, 2, or 3).
BLD = {
    'Garza': 1, 'Yates': 3, 'Zimmer': 3,
    'Flores': 1, 'Lynch': 2,
    'King': 2, 'Meyer': 2, 'Ortiz': 2,
}
NAMES = sorted(BLD)
CO = ['RealProp', 'Southco', 'Trustcorp']
INIT_OWNER = {
    'Garza': 0, 'Yates': 0, 'Zimmer': 0,
    'Flores': 1, 'Lynch': 1,
    'King': 2, 'Meyer': 2, 'Ortiz': 2,
}

def valid_trade(give_a, give_b):
    """Exactly one of the three permitted trade kinds."""
    ca = sorted(BLD[b] for b in give_a)
    cb = sorted(BLD[b] for b in give_b)
    if len(ca) == 1 and len(cb) == 1:
        return ca == cb  # same class, one for one
    if len(ca) == 1 and len(cb) == 2:
        s = ca[0]
        return (s == 1 and cb == [2, 2]) or (s == 2 and cb == [3, 3])
    if len(ca) == 2 and len(cb) == 1:
        s = cb[0]
        return (s == 1 and ca == [2, 2]) or (s == 2 and ca == [3, 3])
    return False

def owned(state, c):
    return [NAMES[k] for k in range(len(NAMES)) if state[k] == c]

def successors(state):
    out = []
    for i, j in itertools.combinations(range(len(CO)), 2):
        oi = owned(state, i)
        oj = owned(state, j)
        for na in (1, 2):
            for sa in itertools.combinations(oi, na):
                for nb in (1, 2):
                    for sb in itertools.combinations(oj, nb):
                        if not valid_trade(sa, sb):
                            continue
                        new = list(state)
                        for b in sa:
                            new[NAMES.index(b)] = j
                        for b in sb:
                            new[NAMES.index(b)] = i
                        out.append(tuple(new))
    return out

# Breadth-first search over all reachable ownership states.
start = tuple(INIT_OWNER[b] for b in NAMES)
seen = {start}
q = deque([start])
while q:
    s = q.popleft()
    for t in successors(s):
        if t not in seen:
            seen.add(t)
            q.append(t)

# Consistency check: 4a + 2b + c is invariant under all permitted trades.
def invariant(state):
    a = sum(1 for b in NAMES if BLD[b] == 1)
    b_ = sum(1 for b in NAMES if BLD[b] == 2)
    c = sum(1 for b in NAMES if BLD[b] == 3)
    return 4 * a + 2 * b_ + c

# Invariant from class counts (depends only on the building set, so check via class totals).
inv_ok = True
base_val = None
for s in seen:
    cls_counts = {1: 0, 2: 0, 3: 0}
    for k, name in enumerate(NAMES):
        cls_counts[BLD[name]] += 1  # total buildings are fixed at 8
    # Class totals are fixed by the building set itself, so the check is structural.
    v = 4 * cls_counts[1] + 2 * cls_counts[2] + cls_counts[3]
    if base_val is None:
        base_val = v
    if v != base_val:
        inv_ok = False

options = {
    'A': ('RealProp', {'Flores', 'Garza'}),
    'B': ('Southco', {'Flores', 'Meyer'}),
    'C': ('Southco', {'Garza', 'Lynch'}),
    'D': ('Trustcorp', {'Flores', 'Ortiz'}),
    'E': ('Trustcorp', {'Garza', 'Meyer'}),
}

possible = {}
for label, (company, target) in options.items():
    c = CO.index(company)
    possible[label] = any(set(owned(s, c)) == target for s in seen)

impossible = [label for label in sorted(options) if not possible[label]]

if len(impossible) == 1:
    final_answer = impossible[0]
else:
    final_answer = 'UNSUPPORTED'

result = {
    "final_answer": final_answer,
    "evidence": {
        "reachable_states": len(seen),
        "possible": possible,
        "impossible": impossible,
        "class_total_check_ok": inv_ok,
    },
}
print(json.dumps(result, separators=(',', ':')))
```

