    """Adjective-class sequence of a phrase; last token is the noun, unknown modifiers are ignored."""
    toks = phrase.split()
    body = toks[:-1]
    seq = [(t, LEX[t]) for t in body if t in LEX]
    unknown = [t for t in body if t not in LEX]
    return seq, unknown

# Derive class-level precedence from the 150 example phrases.
phrases = [p.strip() for p in EXAMPLES.replace("\n", " ").split(";") if p.strip()]
reach = {a: {b: False for b in CATS} for a in CATS}
for ph in phrases:
    seq, _ = seq_of(ph)
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            a, b = seq[i][1], seq[j][1]
            if a != b:
                reach[a][b] = True

# Transitive closure.
for k in CATS:
    for i in CATS:
        for j in CATS:
            if reach[i][k] and reach[k][j]:
                reach[i][j] = True

inconsistent = any(reach[a][b] and reach[b][a] for a in CATS for b in CATS)

if inconsistent:
    print(json.dumps({"final_answer": "UNSUPPORTED",
                      "evidence": {"reason": "example precedence is inconsistent"}}))
else:
    evidence = {}
    correct = []
    for letter, phrase in OPTIONS.items():
        seq, unknown = seq_of(phrase)
        violations = []
        undetermined = 0
        for i in range(len(seq)):
            for j in range(i + 1, len(seq)):
                wi, ci = seq[i]
                wj, cj = seq[j]
                if ci == cj:
                    continue
                if reach[cj][ci]:
                    violations.append(f"{wi}({ci}) before {wj}({cj})")
                elif not reach[ci][cj]:
                    undetermined += 1
        ok = len(violations) == 0
        if ok:
            correct.append(letter)
        evidence[letter] = {
            "order_ok": ok,
            "violations": violations,
            "undetermined_pairs": undetermined,
            "ignored_noun_tokens": unknown,
        }

    final = "".join(correct) if correct else "K"
    result = {
        "final_answer": final,
        "evidence": {
            "class_precedence_edges": {a: [b for b in CATS if reach[a][b]] for a in CATS},
            "options": evidence,
        },
    }
    print(json.dumps(result, indent=2))
