}
MONEY = {"stork": 98}  # no walrus entry: closed world, so Rule3 cannot fire
DOMAIN = ["ant", "stork", "dragon", "mannikin", "mouse", "worm", "crow", "dalmatian",
          "liger", "llama", "walrus", "beetle", "cobra", "dinosaur", "husky",
          "chihuahua", "fish", "goat", "wolf"]
# (preferred, inferior)
SUPERIOR = {("R3", "R1"), ("R5", "R2"), ("R6", "R8"), ("R7", "R4")}


def val(atom, T):
    if atom in T:
        return T[atom] is True
    return atom in FACTS  # closed world: absent atoms are false


def r1(T):
    if val(("negotiates_deal", "ant", "stork"), T) and val(("not_trades", "dalmatian", "stork"), T):
        return [(("builds_plant", "stork"), True)]
    return []


def r2(T):
    if any(val(("builds_plant", x), T) for x in DOMAIN):
        return [(("shouts_beetle", "mouse"), False)]
    return []


def r3(T):
    s, w = MONEY.get("stork"), MONEY.get("walrus")
    if s is not None and w is not None and s > w:
        return [(("builds_plant", "stork"), False)]
    return []


def r4(T):
    if val(("location", "mouse", "Africa"), T):
        return [(("smiles_cobra", "mouse"), True)]
    return []


def r5(T):
    return [(("shouts_beetle", x), True) for x in DOMAIN
            if val(("hugs_dinosaur", x), T) and val(("smiles_cobra", x), T)]


def r6(T):
    if val(("has_instrument", "llama"), T):
        return [(("call_husky", "llama"), True)]
    return []


def r7(T):
    if val(("works_agriculture", "mouse"), T):
        return [(("smiles_cobra", "mouse"), False)]
    return []


def r8(T):
    if any(("acquires_photo", x, "fish") in FACTS for x in DOMAIN):
        return [(("call_husky", "llama"), False)]
    return []


RULES = [("R1", r1), ("R2", r2), ("R3", r3), ("R4", r4),
         ("R5", r5), ("R6", r6), ("R7", r7), ("R8", r8)]


def run():
    T, conflicts, fired = {}, [], []
    for _ in range(10):
        fired = [(name, atom, pol) for name, fn in RULES for atom, pol in fn(T)]
        newT = {}
        for name, atom, pol in fired:
            beaten = any(a2 == atom and p2 != pol and (n2, name) in SUPERIOR
                         for n2, a2, p2 in fired)
            if beaten:
                continue
            if atom in newT and newT[atom] != pol:
                conflicts.append(atom)
            newT[atom] = pol
        if newT == T:
            break
        T = newT
    return T, fired, conflicts


