    def cap(m):
        country, city = m.group(1), m.group(2)
        if country not in CAPITALS:
            raise KeyError(country)
        return "True" if CAPITALS[country] == city else "False"

    s = re.sub(r"\(The capital of ([A-Za-z]+) is ([A-Za-z]+)\.\)", cap, text)
    # Comparison phrases (longest first).
    s = s.replace("is less than or equal to", "<=")
    s = s.replace("is greater than", ">")
    s = s.replace("is less than", "<")
    # Exact rational arithmetic: wrap every integer literal as Fraction.
    s = re.sub(r"(?<![\w.])(\d+)", r"F(\1)", s)
    if " is " in s or "capital" in s:
