        "M 9.12421,1.32559 L 9.89611,1.43773")

TOL = 1e-3
OPTIONS = {
    "A": {4, 5, 9}, "B": {4, 5}, "C": {5, 9}, "D": {4, 1}, "E": {4, 5, 3},
    "F": {4, 7}, "G": {5}, "H": {10}, "I": {6}, "J": {4}, "K": {5, 6},
    "L": {4, 2}, "M": {4, 8}, "N": {8}, "P": {2, 3, 7},
}


def parse(path):
    segs = []
    for sub in path.split("M")[1:]:
        pts = []
        for chunk in sub.split("L"):
            chunk = chunk.strip()
            if not chunk:
                continue
            x, y = chunk.split(",")
            pts.append((float(x), float(y)))
        for a, b in zip(pts, pts[1:]):
            segs.append((a, b))
    return segs


def inside(pt, P):
    x, y = pt
    c = False
    n = len(P)
    for i in range(n):
        x1, y1 = P[i]
        x2, y2 = P[(i + 1) % n]
        if (y1 > y) != (y2 > y):
            xi = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
            if x < xi:
                c = not c
    return c


def on_boundary(pt, P):
    n = len(P)
    for i in range(n):
        a = P[i]
        b = P[(i + 1) % n]
        L = math.dist(a, b)
        t = ((pt[0] - a[0]) * (b[0] - a[0]) + (pt[1] - a[1]) * (b[1] - a[1])) / (L * L)
        t = max(0.0, min(1.0, t))
        q = (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1]))
        if math.dist(q, pt) < TOL:
            return True
    return False


def area(P):
    s = 0.0
    n = len(P)
    for i in range(n):
        x1, y1 = P[i]
        x2, y2 = P[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return s / 2.0


def simplify(P):
    pts = list(P)
    changed = True
    while changed and len(pts) > 3:
        changed = False
        n = len(pts)
        for i in range(n):
            p0, p1, p2 = pts[i - 1], pts[i], pts[(i + 1) % n]
            ax, ay = p1[0] - p0[0], p1[1] - p0[1]
            bx, by = p2[0] - p1[0], p2[1] - p1[1]
            la, lb = math.hypot(ax, ay), math.hypot(bx, by)
            cr = ax * by - ay * bx
            dt = ax * bx + ay * by
            if la > 0 and lb > 0 and abs(cr) <= 1e-3 * la * lb and dt > 0:
                del pts[i]
                changed = True
                break
    return pts


def classify(P, diag):
    n = len(P)
    E = [(P[(i + 1) % n][0] - P[i][0], P[(i + 1) % n][1] - P[i][1]) for i in range(n)]
    L = [math.hypot(*e) for e in E]

    def nsin(i, j):
        return (E[i][0] * E[j][1] - E[i][1] * E[j][0]) / (L[i] * L[j])

    def ncos(i, j):
        return (E[i][0] * E[j][0] + E[i][1] * E[j][1]) / (L[i] * L[j])

    def parallel(i, j):
        return abs(nsin(i, j)) < 1e-3

    sgn = 1 if area(P) > 0 else -1
    convex = all(sgn * nsin(i - 1, i) >= -1e-3 for i in range(n))
    equal = (max(L) / min(L) - 1.0) < 1e-3
    turns = [math.atan2(nsin(i - 1, i), ncos(i - 1, i)) for i in range(n)]
    angles_equal = (max(turns) - min(turns)) < 2e-3
    regular = equal and angles_equal and convex
    right_any = any(abs(ncos(i - 1, i)) < 1e-3 for i in range(n))

    tags = set()
    if n == 3:
        tags.add(4 if right_any else 3)
    elif n == 4:
        rect = all(abs(ncos(i - 1, i)) < 1e-3 for i in range(4))
        pp = [parallel(0, 2), parallel(1, 3)]
        if not diag:
            if rect and equal:
                tags.add(2)
            elif rect:
                tags.add(1)
            elif all(pp):
                tags.add(5)
            elif sum(pp) == 1:
                tags.add(6)
    elif n == 5:
        if not diag:
            if not convex:
                tags.add(8)
            elif regular:
                tags.add(9)
            else:
                tags.add(7)
    elif n == 6:
        if not diag and regular:
            tags.add(10)
    return tags


def main():
    segs = parse(PATH)
    nodes = []

    def node_id(p):
        for i, q in enumerate(nodes):
            if math.dist(p, q) < TOL:
                return i
        nodes.append(p)
        return len(nodes) - 1

    for a, b in segs:
        node_id(a)
        node_id(b)

    edges = set()
    for a, b in segs:
        ia, ib = node_id(a), node_id(b)
        pa, pb = nodes[ia], nodes[ib]
        L = math.dist(pa, pb)
        dx, dy = pb[0] - pa[0], pb[1] - pa[1]
        on = []
        for k, p in enumerate(nodes):
            if k in (ia, ib):
                continue
            t = ((p[0] - pa[0]) * dx + (p[1] - pa[1]) * dy) / (L * L)
            if 0 < t < 1:
                cr = abs((p[0] - pa[0]) * dy - (p[1] - pa[1]) * dx) / L
                if cr < TOL:
                    on.append((t, k))
        chain = [ia] + [k for _, k in sorted(on)] + [ib]
        for u, v in zip(chain, chain[1:]):
            if u != v:
                edges.add(frozenset((u, v)))

    adj = {i: [] for i in range(len(nodes))}
    for e in edges:
        u, v = tuple(e)
        adj[u].append(v)
        adj[v].append(u)
    for u in adj:
        adj[u].sort(key=lambda v: math.atan2(nodes[v][1] - nodes[u][1],
                                             nodes[v][0] - nodes[u][0]))

    seen = set()
    cycles = []
    for u in adj:
        for v in adj[u]:
            if (u, v) in seen:
                continue
            cyc = []
            a, b = u, v
            while (a, b) not in seen:
                seen.add((a, b))
                cyc.append(a)
                nb = adj[b]
                i = nb.index(a)
                c = nb[(i - 1) % len(nb)]
                a, b = b, c
            cycles.append(cyc)

    faces = []
    all_tags = set()
    for cyc in cycles:
        if len(cyc) < 3 or len(set(cyc)) != len(cyc):
            continue
        poly = [nodes[i] for i in cyc]
        if area(poly) <= 1e-9:
            continue
        P = simplify(poly)
        diag = False
        for e in edges:
            u, v = tuple(e)
            mid = ((nodes[u][0] + nodes[v][0]) / 2, (nodes[u][1] + nodes[v][1]) / 2)
            if inside(mid, P) and not on_boundary(mid, P):
                diag = True
        tags = classify(P, diag)
        all_tags |= tags
        faces.append({"n": len(P), "area": round(area(P), 4),
                      "diagonal_drawn": diag, "tags": sorted(tags)})

    if not faces:
        print("UNSUPPORTED")
        return

    matched = sorted(all_tags)
    letter = "O"
    for k, v in OPTIONS.items():
        if v == set(matched):
            letter = k
            break

    result = {
        "final_answer": letter,
        "evidence": {
            "visible_shape_items": matched,
            "bounded_faces": faces,
            "node_count": len(nodes),
            "edge_count": len(edges),
        },
    }
    print(json.dumps(result))


