    "M -11.81053,-7.02023 L -8.24021,-0.48353"
)

TOL = 1e-3          # tolerance for sine / cosine tests (coords are rounded to 5 dp)
LEN_TOL = 1e-3      # relative tolerance for length equality

OPTIONS = {
    "A": {1}, "B": {5, 3}, "C": {4, 3}, "D": {4}, "E": {5, 10}, "F": {1, 3, 7},
    "G": {5}, "H": {4, 5, 6}, "I": {4, 5}, "J": {4, 2, 3}, "K": {4, 3, 10},
    "L": {4, 5, 1}, "M": {3, 6}, "N": {9}, "O": {4, 1}, "P": {5, 7},
}


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def norm(a):
    return math.hypot(a[0], a[1])


def sin_between(u, v):
    return abs(cross(u, v)) / (norm(u) * norm(v))


def cos_between(u, v):
    return dot(u, v) / (norm(u) * norm(v))


def parse_segments(d):
    toks = re.findall(r"[MLZmlz]|[-+]?(?:\d+\.?\d*|\.\d+)", d)
    segs, cmd, cur, i = [], None, None, 0
    while i < len(toks):
        t = toks[i]
        if t.isalpha():
            cmd = t.upper()
            i += 1
            continue
        p = (float(t), float(toks[i + 1]))
        i += 2
        if cmd == "M":
            cur = p
        elif cmd == "L":
            segs.append((cur, p))
            cur = p
    return segs


def key(p):
    return (round(p[0], 6) + 0.0, round(p[1], 6) + 0.0)


def build_graph(segs):
    adj, edges = {}, set()
    for a, b in segs:
        ka, kb = key(a), key(b)
        if ka == kb:
            continue
        edges.add(frozenset((ka, kb)))
        adj.setdefault(ka, set()).add(kb)
        adj.setdefault(kb, set()).add(ka)
    return adj, edges


def find_cycles(adj, maxlen=12):
    nodes = sorted(adj)
    rank = {v: i for i, v in enumerate(nodes)}
    found = {}

    def dfs(start, v, path, onpath):
        for w in adj[v]:
            if w == start and len(path) >= 3:
                canon = frozenset(
                    frozenset((path[i], path[(i + 1) % len(path)])) for i in range(len(path))
                )
                found.setdefault(canon, list(path))
            elif w not in onpath and rank[w] > rank[start] and len(path) < maxlen:
                onpath.add(w)
                path.append(w)
                dfs(start, w, path, onpath)
                path.pop()
                onpath.discard(w)

