    if k == 5:
        if not is_convex(pts):
            return 8 if is_simple(pts) else None
        lens = [norm(e) for e in E]
        equal_sides = max(lens) - min(lens) <= LEN_TOL * max(lens)
        turns = [cos_between(E[i], E[(i + 1) % 5]) for i in range(5)]
        equal_angles = max(turns) - min(turns) < TOL
        return 9 if (equal_sides and equal_angles) else 7
    if k == 6:
        if not is_convex(pts):
            return None
        lens = [norm(e) for e in E]
        equal_sides = max(lens) - min(lens) <= LEN_TOL * max(lens)
        turns = [cos_between(E[i], E[(i + 1) % 6]) for i in range(6)]
        equal_angles = max(turns) - min(turns) < TOL
        return 10 if (equal_sides and equal_angles) else None
    return None


def main():
    segs = parse_segments(PATH)
    adj, edges = build_graph(segs)
    cycles = find_cycles(adj, maxlen=12)

    shapes = []
    for cyc in cycles:
        pts = reduce_corners(cyc)
        if not (3 <= len(pts) <= 6):
            continue
        if abs(area2(pts)) < 1e-9:
            continue
        if not is_simple(pts):
            continue
        diag = has_diagonal(pts, edges)
        cat = classify(pts, diag)
        shapes.append({"corners": len(pts), "diagonals_drawn": diag, "category": cat})

    matched = {s["category"] for s in shapes if s["category"] is not None}
    options = [L for L, s in OPTIONS.items() if s == matched]

    if len(options) == 1:
        final = "(" + options[0] + ")"
    else:
        final = "UNSUPPORTED"

    out = {
        "final_answer": final,
        "evidence": {
            "segments": len(segs),
            "nodes": len(adj),
            "cycles_found": len(cycles),
            "closed_shapes": shapes,
            "matched_categories": sorted(matched),
            "matching_options": options,
        },
    }
    print(json.dumps(out, separators=(",", ":")))


