    area = sum(cross(C[i], C[(i + 1) % n]) for i in range(n))
    sgn = 1 if area > 0 else -1
    turns = [cross(sub(C[i], C[i - 1]), sub(C[(i + 1) % n], C[i])) for i in range(n)]
    return all(t * sgn >= 0 for t in turns)

def regular(C):
    n = len(C)
    sides = []
    ang = []
    for i in range(n):
        v = sub(C[(i + 1) % n], C[i])
        sides.append(math.hypot(float(v[0]), float(v[1])))
        u = sub(C[i - 1], C[i]); w = sub(C[(i + 1) % n], C[i])
        nu = math.hypot(float(u[0]), float(u[1])); nw = math.hypot(float(w[0]), float(w[1]))
        c = float(dot(u, w)) / (nu * nw)
        ang.append(math.acos(max(-1.0, min(1.0, c))))
    return (max(sides) - min(sides) < 1e-3) and (max(ang) - min(ang) < 1e-3)

def classify(C):
    n = len(C)
    if n == 3:
        right = any(dot(sub(C[i - 1], C[i]), sub(C[(i + 1) % 3], C[i])) == 0 for i in range(3))
        return ['4' if right else '3']
    if has_diag(C):
        return []
    if n == 4:
        d = [sub(C[(i + 1) % 4], C[i]) for i in range(4)]
        p02 = cross(d[0], d[2]) == 0
        p13 = cross(d[1], d[3]) == 0
        rect = all(dot(d[i], d[(i + 1) % 4]) == 0 for i in range(4))
        if p02 and p13:
            if not rect:
                return ['5']
            sq = dot(d[0], d[0]) == dot(d[1], d[1])
            return ['2'] if sq else ['1']
        if p02 or p13:
            return ['6']
        return []
    if n == 5:
        convex = is_convex(C)
        if convex and regular(C):
            return ['9']
        return ['7'] if convex else ['8']
    if n == 6 and regular(C):
        return ['10']
    return []

OPTIONS = {
    'A': {'2'}, 'B': {'9'}, 'C': {'8'}, 'D': {'4'}, 'E': {'2', '4', '6'}, 'F': set(),
    'G': {'3'}, 'H': {'8', '6'}, 'I': {'2', '8'}, 'J': {'3', '4', '5'}, 'K': {'8', '3', '10'},
    'L': {'2', '1', '5', '10'}, 'M': {'2', '8', '1', '9'}, 'N': {'2', '7'}, 'O': {'2', '3', '6'},
    'P': {'2', '1', '6', '10'}
}

found = set()
cycle_info = []
for key, poly in found_cycles.items():
    C = corners(poly)
    ids = classify(C) if len(C) >= 3 else []
    found.update(ids)
    cycle_info.append({"corners": len(C),
                       "convex": is_convex(C) if len(C) >= 3 else None,
                       "ids": ids})

matches = [k for k, v in OPTIONS.items() if v == found]
final = matches[0] if matches else 'F'

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "segments": len(segs),
        "nodes": len(adj),
        "edges": len(edges),
        "closed_cycles": cycle_info,
        "viewable_option_ids": sorted(found)
    }
}, separators=(",", ":")))
