PREFS = {('R6', 'R3'), ('R7', 'R4')}  # (winner, loser)

BASE_T = {('has', 'basenji', 'cutter'), ('has', 'basenji', 'knife'),
          ('negotiates', 'goat', 'pigeon'), ('trades', 'monkey', 'goat')}
BASE_F = set()

# Derived facts from the stated game state
sharp_items = [a for a in BASE_T if a[0] == 'has' and a[1] == 'basenji' and a[2] in SHARP]
if sharp_items:
    BASE_T.add(('sharp', 'basenji'))

card_color = 'violet'
if card_color in PRIMARY:
    BASE_T.add(('primary_card', 'basenji'))
else:
    BASE_F.add(('primary_card', 'basenji'))

state = {'T': set(BASE_T), 'F': set(BASE_F)}


def v(a):
    if a in state['T']:
        return True
    if a in state['F']:
        return False
    return None


def lit(a, s=True):
    x = v(a)
    if x is None:
        return None
    return x if s else (not x)


def conj(*xs):
    if any(x is False for x in xs):
        return False
    if all(x is True for x in xs):
        return True
    return None


def disj(*xs):
    if any(x is True for x in xs):
        return True
    if all(x is False for x in xs):
        return False
    return None


rules = []  # (name, premise_fn, conclusion_atom, sign)
rules.append(('R1', lambda: lit(('sharp', 'basenji')), ('disarm', 'basenji', 'dove'), False))
rules.append(('R2', lambda: lit(('primary_card', 'basenji')), ('disarm', 'basenji', 'dove'), False))
rules.append(('R3', lambda: lit(('negotiates', 'goat', 'pigeon')), ('neglect', 'goat', 'goose'), False))
rules.append(('R6', lambda: conj(lit(('leave', 'beetle', 'goat'), False),
                                 lit(('trades', 'monkey', 'goat'))),
              ('neglect', 'goat', 'goose'), True))
for x in ANIMALS:
    rules.append(('R5', lambda x=x: lit(('neglect', x, 'goose'), False),
                  ('surrender', x, 'chinchilla'), True))
    rules.append(('R8', lambda x=x: lit(('disarm', x, 'dove'), False),
                  ('wants', x, 'reindeer'), True))
    rules.append(('R7', lambda x=x: conj(lit(('destroy_wall', x), False),
                                         lit(('wants', x, 'reindeer'))),
                  ('hide', x, 'songbird'), False))
rules.append(('R4', lambda: disj(*[lit(('surrender', x, 'chinchilla')) for x in ANIMALS]),
              ('hide', 'basenji', 'songbird'), True))


def resolve(atom, firing):
    trues = [(n, s) for n, s, p in firing if p is True]
    if not trues:
        return None
    signs = {s for _, s in trues}
    if len(signs) == 1:
        return signs.pop()
    for s in signs:
        winners = [n for n, ss in trues if ss == s]
        losers = [n for n, ss in trues if ss != s]
        if all((w, l) in PREFS for w in winners for l in losers):
            return s
    return None


for _ in range(30):
