    for name, prem, atom, sign in rules:
        firing.setdefault(atom, []).append((name, sign, prem()))
    newT = set(BASE_T)
    newF = set(BASE_F)
    for atom, fl in firing.items():
        r = resolve(atom, fl)
        if r is True:
            newT.add(atom)
        elif r is False:
            newF.add(atom)
    if newT == state['T'] and newF == state['F']:
        break
    state['T'], state['F'] = newT, newF

