CHOICES = {2: "A", 3: "B", 4: "C", 5: "D", 6: "E"}


def satisfies(order):
    # order[i] is the color of the i-th house Ralph passed (0 = first).
    pos = {color: i for i, color in enumerate(order)}
    rules = {
        "orange_before_red": pos["orange"] < pos["red"],
        "blue_before_yellow": pos["blue"] < pos["yellow"],
        "blue_not_adjacent_yellow": abs(pos["blue"] - pos["yellow"]) != 1,
        "green_after_blue": pos["blue"] < pos["green"],
        "green_before_red": pos["green"] < pos["red"],
    }
    return rules


total = 0
valid = []
rule_hits = {}
for order in itertools.permutations(COLORS):
    rules = satisfies(order)
    for name, ok in rules.items():
        rule_hits[name] = rule_hits.get(name, 0) + (1 if ok else 0)
    if all(rules.values()):
        valid.append(order)
    total += 1

count = len(valid)

if count in CHOICES:
    final = CHOICES[count]
    final_answer = f"{final} ({count})"
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "total_permutations": total,
    "valid_count": count,
    "per_rule_satisfied_counts": rule_hits,
    "valid_orderings": [list(o) for o in valid],
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
