    for atom, rs in derivs.items():
        P = {r for s, r in rs if s}
        N = {r for s, r in rs if not s}
        if P and not N:
            T.add(atom)
        elif N and not P:
            F.add(atom)
        elif P and N:
            if all((p, n) in PREF for p in P for n in N):
                T.add(atom)
            elif all((n, p) in PREF for p in P for n in N):
                F.add(atom)
    return T, F


def fire(T, F):
    out = []

    def add(a, s, r):
        out.append((a, s, r))

    def ex(pred):
        return any((pred, x) in T for x in ANIMALS)

    for x in ANIMALS:
        if ("shouts_beaver", x) in T:
            add(("unites_ostrich", x), True, "R1")          # R1
        if ("shouts_peafowl", x) in T:
            add(("shouts_beaver", x), True, "R22")          # R22
        if ("tear_badger", x) in F:
