        if ("wants_fangtooth", x) in T:
            add(("shouts_beetle", x), False, "R14")         # R14
        if ("refuse_dinosaur", x) in F:
            add(("reveals_zebra", x), True, "R17")          # R17
        if ("shouts_beetle", x) in F and ("reveals_zebra", x) in T:
            add(("trades_stork", x), False, "R18")          # R18
        if ("refuse_badger", x) in T:
            add(("shouts_dragonfly", x), True, "R19")       # R19
        if ("shouts_dragonfly", x) in T:
            add(("wants_fangtooth", x), True, "R20")        # R20
        if ("reduced_hours", x) in T:
            add(("tear_dove", x), True, "R23")              # R23

    if ex("tear_dove"):
        add(("takes_emperor", "woodpecker"), True, "R2")    # R2
    if ex("persuades_rhino"):
        add(("shouts_beaver", "swan"), False, "R3")         # R3
    if ("trades_stork", "bee") in F and ("trades_stork", "beetle") in T:
        add(("wants_goat", "stork"), True, "R4")            # R4
    if ex("enjoys_ant"):
        add(("shouts_peafowl", "swan"), False, "R6")        # R6
    if ex("unites_ostrich"):
        add(("trades_stork", "beetle"), True, "R7")         # R7
    if ("smiles_bee", "flamingo") in T:
        add(("shouts_beetle", "bee"), True, "R9")           # R9
    if ex("wants_goat"):
        add(("capture_king_pigeon", "finch"), False, "R10") # R10
    if ("age_under_4", "frog") in T:
        add(("destroy_wall_swan", "frog"), False, "R11")    # R11
    if ex("takes_emperor"):
        add(("refuse_dinosaur", "bee"), False, "R13")       # R13
    if ex("trades_bison"):
        add(("unites_ostrich", "swan"), False, "R15")       # R15
    if any(("card_color", "frog", c) in T and c in PRIMARY for c in PRIMARY | {"yellow"}):
        add(("destroy_wall_swan", "frog"), False, "R16")    # R16
    if any(("has_food", "frog", f) in T and ("leafy_green", f) in T for f in ["spinach"]):
        add(("destroy_wall_swan", "frog"), True, "R21")     # R21
    if ("destroy_wall_swan", "frog") in T:
        add(("shouts_peafowl", "swan"), True, "R24")        # R24
    return out


derivs = {}


def addd(atom, sign, rule):
    derivs.setdefault(atom, set()).add((sign, rule))


for a, s in FACTS:
    addd(a, s, "fact")

for _ in range(200):
    T, F = status(derivs)
    before = sum(len(v) for v in derivs.values())
    for a, s, r in fire(T, F):
        addd(a, s, r)
    if sum(len(v) for v in derivs.values()) == before:
        break

T, F = status(derivs)
target = ("capture_king_pigeon", "finch")
if target in T:
