import json
from itertools import product

# Known facts from the problem statement.
FACTS = {
    "flamingo_trades_with_songbird": True,
    "songbird_has_computer": True,  # not used by any rule: Rule3 needs an internet device
}

# Atoms the problem does not state. Enumerate every truth assignment.
UNKNOWN_ATOMS = [
    "dugong_trades_with_songbird",   # Rule1 antecedent
    "songbird_has_internet_device",  # Rule3 antecedent
    "crab_leaves_finch_houses",      # Rule4 antecedent (the crab is the animal that leaves)
]


def derive_swears_beetle(world):
    """Return 'proved', 'disproved', or 'unknown' for crab swears to beetle in one world."""
    # Rule1: flamingo trades AND dugong trades -> songbird NOT smiles at crab (preferred over Rule3).
    rule1_fires = FACTS["flamingo_trades_with_songbird"] and world["dugong_trades_with_songbird"]

    # Rule3: internet device -> songbird smiles at crab, unless Rule1 concludes otherwise.
    smiles = world["songbird_has_internet_device"] and not rule1_fires

    # Rule4: leaves finch houses -> crab swears to beetle (preferred over Rule2).
    if world["crab_leaves_finch_houses"]:
        return "proved"

    # Rule2: smiles at crab -> crab does NOT swear to beetle.
    if smiles:
        return "disproved"

    # No rule supports either conclusion in this world.
    return "unknown"


def enumerate_worlds():
    for values in product([False, True], repeat=len(UNKNOWN_ATOMS)):
        yield dict(zip(UNKNOWN_ATOMS, values))


outcomes = {}
for w in enumerate_worlds():
    key = json.dumps(w, sort_keys=True)
    outcomes[key] = derive_swears_beetle(w)

distinct = set(outcomes.values())

if len(distinct) == 1:
    final_answer = distinct.pop()
else:
    # The status depends on the unstated atoms, so it is not determined by the problem.
    final_answer = "unknown"

counts = {}
for v in outcomes.values():
    counts[v] = counts.get(v, 0) + 1

evidence = {
    "worlds_checked": len(outcomes),
    "outcome_counts": counts,
    "rule1_preferred_over_rule3": True,
    "rule4_preferred_over_rule2": True,
    "unstated_atoms": UNKNOWN_ATOMS,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}, sort_keys=True))
