# Claimed final answer: (-inf, -1/3) U (1, inf)
def claimed(x):
    return x < F(-1, 3) or x > 1

def premise_holds(a, b, c, xs):
    # Premise: solution set of a x^2 + b x + c <= 0 is exactly {x <= -1 or x >= 3}
    for x in xs:
        lhs = a * x * x + b * x + c <= 0
        target = (x <= -1) or (x >= 3)
        if lhs != target:
            return False
    return True

# Test points: rationals in [-10, 10] with step 1/4, including -1, 3, -1/3, 1
