from fractions import Fraction as Fr

CLAIMED_COUNT = 1  # claimed final answer: number of real solutions


def f_exact(t):
    return 2 * t * t / (1 + t * t)


def f_float(t):
    return 2.0 * t * t / (1.0 + t * t)


def h(x):
    # Single-variable reduction: x1 = f(f(f(x1))).
    return f_float(f_float(f_float(x))) - x


def exact_residuals(x1, x2, x3):
    # Evaluate both sides of each equation exactly.
    lhs1, rhs1 = f_exact(x1), x2
    lhs2, rhs2 = f_exact(x2), x3
    lhs3, rhs3 = f_exact(x3), x1
    return [(lhs1, rhs1), (lhs2, rhs2), (lhs3, rhs3)]


def is_exact_solution(x1, x2, x3):
    return all(l == r for l, r in exact_residuals(x1, x2, x3))


# 1) Exact verification of candidate solutions with Fractions.
candidates = [
    (Fr(0), Fr(0), Fr(0)),
    (Fr(1), Fr(1), Fr(1)),
]

exact_valid = []
print("Exact verification of candidate solutions:")
for x1, x2, x3 in candidates:
    ok = is_exact_solution(x1, x2, x3)
    print(f"  candidate (x1,x2,x3) = ({x1}, {x2}, {x3})")
    for i, (l, r) in enumerate(exact_residuals(x1, x2, x3), start=1):
        print(f"    equation {i}: LHS = {l}, RHS = {r}, equal = {l == r}")
    if ok:
        exact_valid.append((x1, x2, x3))

# 2) Numerical sign-change search on [0, 2] for the reduced equation.
#    Any real solution has x_i = f(x_{i-1}) >= 0 and < 2, so [0, 2] is sufficient.
N = 200000
grid = [2.0 * i / N for i in range(N + 1)]
roots = []


def add_root(r):
    for s in roots:
        if abs(s - r) < 1e-9:
            return
    roots.append(r)


for i in range(N):
    a, b = grid[i], grid[i + 1]
    ha, hb = h(a), h(b)
    if abs(ha) < 1e-13:
        add_root(a)
    if ha * hb < 0:
        lo, hi = a, b
        for _ in range(200):
            mid = 0.5 * (lo + hi)
            if h(lo) * h(mid) <= 0:
                hi = mid
            else:
                lo = mid
        add_root(0.5 * (lo + hi))
if abs(h(grid[-1])) < 1e-13:
    add_root(grid[-1])

roots.sort()
print()
print(f"Grid search on [0, 2] with N = {N} intervals (step {2.0/N:.1e}):")
print(f"  distinct x1 roots found: {len(roots)}")
for r in roots:
    x2 = f_float(r)
    x3 = f_float(x2)
    res = f_float(x3) - r
    print(f"  x1 = {r:.12f}, x2 = {x2:.12f}, x3 = {x3:.12f}, "
          f"residual of eq3 = {res:.3e}")

# 3) Report.
count_exact = len(exact_valid)
print()
print(f"Exactly verified solutions: {count_exact}")
for s in exact_valid:
    print(f"  {s}")
print(f"Claimed count: {CLAIMED_COUNT}")
print("Grid search is not a completeness proof; it is used only to look for further roots.")

if count_exact > CLAIMED_COUNT:
    print("CHECK FAIL")
    print(f"Counterexample: the exactly verified solutions {exact_valid} number {count_exact}, "
          f"which exceeds the claimed count {CLAIMED_COUNT}.")
elif count_exact == CLAIMED_COUNT and len(roots) <= CLAIMED_COUNT:
    print("CHECK UNKNOWN")
    print("No counterexample in the searched grid; completeness not proven.")
else:
    print("CHECK UNKNOWN")
    print("Claim not refuted by exact checks; completeness not proven.")
